contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try any callee and calldata; assert that either forward reverts (reverted==true)
    // or forward returns and the external call succeeded and this contract's balance didn't increase.
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balance of this test contract before calling forward
        uint256 balBefore = address(this).balance;

        bool reverted;
        // call forward and observe whether it reverts
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call, test contract's balance should not have increased as a result of a successful forward.
        // The general rule: either reverted==true, or (reverted==false and address(this).balance == balBefore)
        assert(reverted || (address(this).balance == balBefore));
    }

    // Allow receiving Ether from callee if needed during testing
    receive() external payable {}
}

